std::vector<Point2d> intersections;
size_t n = segments.size();

for (size_t i = 0; i < n; ++i) {
    for (size_t j = i + 1; j < n; ++j) {
        const Segment2d& s1 = segments[i];
        const Segment2d& s2 = segments[j];

        double x1 = s1.start.x;
        double y1 = s1.start.y;
        double x2 = s1.end.x;
        double y2 = s1.end.y;

        double x3 = s2.start.x;
        double y3 = s2.start.y;
        double x4 = s2.end.x;
        double y4 = s2.end.y;

        double denom = (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1);
        double numA = (x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3);
        double numB = (x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3);

        if (std::abs(denom) < 1e-9) {
            // Parallel or collinear
            // For simplicity in general intersection tasks, we check endpoints 
            // if they lie on the other segment for collinear overlap
            auto onSegment = [](double px, double py, double ax, double ay, double bx, double by) {
                return px >= std::min(ax, bx) - 1e-9 && px <= std::max(ax, bx) + 1e-9 &&
                       py >= std::min(ay, by) - 1e-9 && py <= std::max(ay, by) + 1e-9;
            };

            // Check if collinear
            if (std::abs(numA) < 1e-9 && std::abs(numB) < 1e-9) {
                if (onSegment(x1, y1, x3, y3, x4, y4)) intersections.push_back({x1, y1});
                if (onSegment(x2, y2, x3, y3, x4, y4)) intersections.push_back({x2, y2});
                if (onSegment(x3, y3, x1, y1, x2, y2)) intersections.push_back({x3, y3});
                if (onSegment(x4, y4, x1, y1, x2, y2)) intersections.push_back({x4, y4});
            }
            continue;
        }

        double uA = numA / denom;
        double uB = numB / denom;

        if (uA >= 0.0 && uA <= 1.0 && uB >= 0.0 && uB <= 1.0) {
            intersections.push_back({x1 + uA * (x2 - x1), y1 + uA * (y2 - y1)});
        }
    }
}

// Remove duplicates if necessary
std::sort(intersections.begin(), intersections.end(), [](const Point2d& a, const Point2d& b) {
    return (std::abs(a.x - b.x) < 1e-9) ? (a.y < b.y - 1e-9) : (a.x < b.x - 1e-9);
});
intersections.erase(std::unique(intersections.begin(), intersections.end(), [](const Point2d& a, const Point2d& b) {
    return std::abs(a.x - b.x) < 1e-9 && std::abs(a.y - b.y) < 1e-9;
}), intersections.end());

return intersections;
// END_CODE

